renderer.render(scene,camera);if(Math.floor(elapsed*5)%2===0){fishLabel.textContent=compact(game.fish);rateLabel.textContent=compact(rate())}if(saveTick>5){saveTick=0;saveGame()}}
requestAnimationFrame(animate);
function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<700?39:36;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight)}addEventListener('resize',resize);
let audioOn=false,audioCtx;document.querySelector('#sound').addEventListener('click',()=>{audioOn=!audioOn;document.querySelector('#sound').textContent=audioOn?'♫':'♪';message(audioOn?'Sound on':'Sound off')});
