];
const perks=perkGroups.flatMap(group=>group.perks.map(([id,name,effect,value,max,desc,requires])=>({id,name,effect,value,max,desc,requires,icon:group.icon,group:group.name,cost:requires?2:1})));
let save;try{save=JSON.parse(localStorage.pondPals||'{}')}catch{save={}};
const game={fish:Math.max(0,Number(save.fish)||0),total:Math.max(0,Number(save.total)||0),runFish:Math.max(0,Number(save.runFish??save.total)||0),rebirths:Math.max(0,Number(save.rebirths)||0),gold:Math.max(0,Number(save.gold)||0),perks:Object.assign({},save.perks||{}),counts:Object.assign({pup:0,buddy:0,family:0,net:0},save.counts||{})};
function bonus(key){return perks.reduce((n,p)=>n+(p.effect===key?(game.perks[p.id]||0)*p.value:0),0)}
function rate(){return defs.reduce((n,d)=>n+(d.rate||0)*game.counts[d.id],0)*(1+bonus('otterSpeed'))*(1+bonus('otterYield'))*(1+bonus('otterAll'))*(1+bonus('fishValue'))*(1+bonus('allGather'))}function power(){return (1+game.counts.net*2+bonus('tapFlat'))*(1+bonus('tapPct'))*(1+bonus('fishValue'))*(1+bonus('allGather'))}function critChance(){return Math.min(.8,bonus('critChance'))}function helperCount(){return game.counts.pup+game.counts.buddy+game.counts.family}
function rebirthTarget(){return Math.max(1000,Math.floor(10000*Math.pow(1.65,game.rebirths)*(1-Math.min(.5,bonus('thresholdCut')))))}function rebirthReward(){if(game.runFish<rebirthTarget())return Math.max(1,Math.floor(game.runFish/rebirthTarget()*2*(1+bonus('goldBonus'))));return Math.max(1,Math.floor(game.runFish/rebirthTarget()*2*(1+bonus('goldBonus'))))}
function compact(n){if(n<1000)return Math.floor(n).toLocaleString();const units=['K','M','B','T','Qa','Qi'];let i=-1;do{n/=1000;i++}while(n>=1000&&i<units.length-1);return n.toFixed(n<10?1:0)+units[i]}
function saveGame(){try{localStorage.pondPals=JSON.stringify({fish:game.fish,total:game.total,runFish:game.runFish,rebirths:game.rebirths,gold:game.gold,perks:game.perks,counts:game.counts})}catch{}}
function shopPrice(d){return Math.max(1,Math.floor(d.cost*Math.pow(1.16,game.counts[d.id])*(1-Math.min(.5,bonus('discount')))))}
function updateMeter(){const target=rebirthTarget(),progress=Math.min(100,game.runFish/target*100),ready=game.runFish>=target;document.querySelector('#rebirth-progress-label').textContent=Math.floor(progress)+'%';document.querySelector('#rebirth-fill').style.width=progress+'%';document.querySelector('#rebirth-reward').textContent='✨ +'+compact(rebirthReward())+' golden fish';document.querySelector('#do-rebirth').disabled=!ready;document.querySelector('#do-rebirth').textContent=ready?'REBIRTH NOW':'KEEP GROWING';document.querySelector('#gold-fish').textContent=compact(game.gold);document.querySelector('#open-rebirth').textContent=ready?'🌟 Rebirth!':'🌙 Ascend'}
function ui(){fishLabel.textContent=compact(game.fish);rateLabel.textContent=compact(rate());totalLabel.textContent=compact(helperCount());for(const d of defs){const btn=document.querySelector('#buy-'+d.id),price=shopPrice(d);btn.querySelector('.price').textContent='🐟 '+compact(price);btn.classList.toggle('afford',game.fish>=price);btn.classList.toggle('locked',game.fish<price);btn.querySelector('.qty').textContent='×'+game.counts[d.id]}updateMeter()}
for(const d of defs){const card=document.createElement('button');card.className='buy-card';card.id='buy-'+d.id;card.innerHTML=`<span class="item-icon">${d.icon}</span><span class="item-info"><b>${d.name}</b><small>${d.desc}</small></span><span class="price">🐟 ${d.cost}</span><span class="qty">×0</span>`;card.addEventListener('click',()=>buy(d));shop.append(card)}
let toastTimer;function message(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),1250)}
function buy(d){const price=shopPrice(d);if(game.fish<price){message('A few more fish!');return}game.fish-=price;game.counts[d.id]++;if(d.id==='net')message('✨ Shiny net!');else message('🦦 New otter friend!');addOtter();ui();saveGame()}

