function perkRank(p){return Math.max(0,Math.min(p.max,Math.floor(Number(game.perks[p.id])||0)))}
function perkCost(p){return p.cost*(perkRank(p)+1)}
function perkUnlocked(p){return !p.requires||perkRank(perks.find(item=>item.id===p.requires))>0}
function renderPerks(){const tree=document.querySelector('#perk-tree');tree.innerHTML='';for(const group of perkGroups){const section=document.createElement('section');section.className='perk-group';const title=document.createElement('h3');title.textContent=group.name;const grid=document.createElement('div');grid.className='perk-grid';for(const raw of group.perks){const p=perks.find(item=>item.id===raw[0]),rank=perkRank(p),unlocked=perkUnlocked(p),maxed=rank>=p.max,afford=game.gold>=perkCost(p);const button=document.createElement('button');button.className='perk'+(rank?' owned':'')+(!unlocked?' locked':'');button.disabled=maxed||!unlocked||!afford;button.setAttribute('aria-label',`${p.name}, rank ${rank} of ${p.max}, costs ${perkCost(p)} golden fish`);button.innerHTML=`<span class="perk-icon">${p.icon}</span><b>${p.name}</b><span class="perk-cost">${maxed?'MAX':`🟡 ${perkCost(p)}`}</span><small>${p.desc}<br>Rank ${rank}/${p.max}${p.requires&&!unlocked?' · unlock previous perk':''}</small>`;button.addEventListener('click',()=>buyPerk(p));grid.append(button)}section.append(title,grid);tree.append(section)}}
function buyPerk(p){const cost=perkCost(p);if(!perkUnlocked(p)||perkRank(p)>=p.max||game.gold<cost)return;game.gold-=cost;game.perks[p.id]=perkRank(p)+1;message('✨ '+p.name+' upgraded!');renderPerks();ui();saveGame()}
function buy(d){const price=shopPrice(d);if(game.fish<price){message('A few more fish!');return}game.fish-=price;game.counts[d.id]++;if(d.id==='net')message('✨ Shiny net!');else message('🦦 New otter friend!');addOtter();ui();saveGame()}

