*{
box-sizing:border-box}
html,body{
margin:0;width:100%;height:100%;overflow:hidden;font-family:ui-rounded,"Arial Rounded MT Bold",system-ui,sans-serif;color:var(--ink);background:#9de3d5}
button{
font:inherit;color:inherit;border:0;cursor:pointer}
