.topbar{
position:absolute;top:20px;left:22px;right:22px;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none;gap:12px}
.brand,.counter,.sound{
pointer-events:auto;background:rgba(255,250,235,.9);box-shadow:0 7px 0 rgba(26,104,111,.12),0 12px 30px #227d8050;backdrop-filter:blur(12px);border:2px solid #fff9e2;border-radius:22px}
.brand{
