if(game.lifetimeFish<worlds[game.selectedWorld].requirement)game.selectedWorld=0;
 const combo={progress:0,tier:0,idle:0};
 const comboSkills=[{id:'combo_overflow',name:'Combo Overflow',icon:'🌊',cost:4,max:3,requires:null,description:'Fill the bar again after a combo to climb up to three extra tiers. Each tier boosts taps by +0.5×.'},{id:'combo_calm',name:'Calm Current',icon:'🫧',cost:3,max:3,requires:'combo_overflow',description:'Your combo bar drains 18% slower per rank when you pause tapping.'}];
 function comboRank(id){return Math.max(0,Math.min(comboSkills.find(s=>s.id===id)?.max||0,Math.floor(Number(game.perks[id])||0)))}
 function comboCost(skill){return skill.cost*(comboRank(skill.id)+1)}
 function comboUnlocked(skill){return !skill.requires||comboRank(skill.requires)>0}
 function comboMaxTier(){return 1+comboRank('combo_overflow')}
 function comboMultiplier(){return 1+.5*combo.tier}
 function advanceCombo(){combo.idle=0;if(combo.tier>=comboMaxTier())return;combo.progress=Math.min(1,combo.progress+.2);if(combo.progress>=1){combo.tier++;combo.progress=combo.tier<comboMaxTier()?0:1}updateComboHud()}
 function updateComboHud(){const fill=document.querySelector('#combo-fill'),label=document.querySelector('#combo-label'),caption=document.querySelector('#combo-caption');fill.style.width=(combo.progress*100)+'%';label.textContent='x'+comboMultiplier().toFixed(1);caption.textContent=combo.tier?`Tier ${combo.tier}/${comboMaxTier()} · tap to build more`:'Tap the fish to build your combo!';document.querySelector('#combo-hud').classList.toggle('active',combo.tier>0)}
 function decayCombo(dt){if(!combo.tier&&!combo.progress)return;combo.idle+=dt;if(combo.idle<.8)return;const decay=.34*Math.pow(.82,comboRank('combo_calm'));combo.progress=Math.max(0,combo.progress-decay*dt);if(combo.progress===0){combo.tier=0;combo.idle=0}updateComboHud()}

